local R=loadstring(game:HttpGet('https://sirius.menu/rayfield'))()local logs={}local hooked={}local spyEnabled=true local function fmt(v,d)d=d or 0 if d>3 then return "..." end local t=typeof(v)if t=="string"then return '"'..v..'"'elseif t=="number"or t=="boolean"or t=="nil"then return tostring(v)elseif t=="Instance"then return v:GetFullName()elseif t=="Vector3"then return string.format("Vector3.new(%g,%g,%g)",v.X,v.Y,v.Z)elseif t=="CFrame"then return "CFrame.new("..tostring(v.Position)..")"elseif t=="Color3"then return string.format("Color3.fromRGB(%d,%d,%d)",v.R*255,v.G*255,v.B*255)elseif t=="table"then local p={}for k,x in pairs(v)do table.insert(p,tostring(k).."="..fmt(x,d+1))end return "{"..table.concat(p,",").."}"end return tostring(v)end local function logCall(kind,name,path,args)if not spyEnabled then return end local argStr="" for i,a in ipairs(args)do argStr=argStr.."\n    ["..i.."] "..fmt(a)end local entry=string.format("[%s] %s:%s\n  Path: %s%s",os.date("%H:%M:%S"),kind,name,path,argStr)table.insert(logs,1,entry)if #logs>200 then table.remove(logs)end end local function hook(o)if hooked[o]then return end hooked[o]=true if o:IsA("RemoteEvent")or o:IsA("RemoteFunction")or o:IsA("BindableEvent")then local mt=getrawmetatable(game)if mt and not mt.___spy then local old=mt.__namecall setreadonly(mt,false)mt.__namecall=newcclosure(function(s,...)local m=getnamecallmethod()if spyEnabled and s==o and(m=="FireServer"or m=="InvokeServer"or m=="Fire")then logCall(s.ClassName,s.Name,s:GetFullName(),{...})end return old(s,...)end)setreadonly(mt,true)mt.___spy=true end end end local function scan()for _,o in ipairs(game:GetDescendants())do hook(o)end end local W=R:CreateWindow({Name="Simple Spy",LoadingTitle="Loading...",LoadingSubtitle="Remote Logger",ConfigurationSaving={Enabled=false},KeySystem=false})local T=W:CreateTab("Spy",4483362458)T:CreateButton({Name="Rescan Remotes",Callback=function()scan()R:Notify({Title="Spy",Content="Rescanned all remotes",Duration=3})end})T:CreateButton({Name="Clear Logs",Callback=function()logs={}R:Notify({Title="Spy",Content="Cleared",Duration=2})end})T:CreateButton({Name="Toggle Spy (On/Off)",Callback=function()spyEnabled=not spyEnabled R:Notify({Title="Spy",Content=spyEnabled and "Enabled" or "Disabled",Duration=2})end})T:CreateButton({Name="Copy All Logs",Callback=function()local out=#logs==0 and "-- No logs --" or table.concat(logs,"\n\n")if setclipboard then setclipboard(out)R:Notify({Title="Spy",Content="Copied "..#logs.." entries",Duration=3})else R:Notify({Title="Spy",Content="Clipboard unavailable",Duration=3})end end})local box=T:CreateInput({Name="Live Log",PlaceholderText="Waiting for remote calls...",RemoveTextAfterFocusLost=false,Callback=function()end})task.spawn(function()while task.wait(0.5)do local txt=#logs==0 and "Waiting for remote calls..." or table.concat(logs,"\n\n")if #txt>6000 then txt=txt:sub(1,6000).."\n...(truncated)"end pcall(function()box:Set(txt)end)end end)game.DescendantAdded:Connect(hook)scan()R:Notify({Title="Simple Spy",Content="Loaded. Monitoring remotes.",Duration=4})
